import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
for k in G: print(k, len(G[k]), len(G[k][0]))

import numpy as np
for k in ['Demo pair 1 input','Demo pair 1 output']:
    print(k); print(np.array(G[k]))

def transform(g):
    h=len(g); w=len(g[0])
    out=[row[:] for row in g]
    threes=[(i,j) for i in range(h) for j in range(w) if g[i][j]==3]
    for r,c in threes:
        for j in range(c-2,c+3):
            if 0<=r-2<h and 0<=j<w: out[r-2][j]=5
        for i in (r-1,r,r+1):
            for j in (c-2,c+2):
                if 0<=i<h and 0<=j<w: out[i][j]=2
        if 0<=r-1<h and 0<=c<w: out[r-1][c]=5
        if 0<=r+2<h:
            out[r+2]=[2]*w
            for j in range(c-2,c+3):
                if 0<=j<w: out[r+2][j]=8
    return out
D=G['Demo pair 1 input']
print(transform(D)==G['Demo pair 1 output'])
print(json.dumps(transform(G['Test input'])))

